// Deliberately narrow PostgreSQL test transport lexer, not a SQL parser.
// Supported: standard_conforming_strings=on, ordinary/E strings, quoted names,
// dollar constants, nested comments and contiguous $1..$N parameters in code.
const identifier=/[A-Za-z0-9_$\u0080-\uffff]/;
const whitespace=/[ \t\n\r\f\v]/;
const quoteText=value=>`E'${value.replaceAll('\\','\\\\').replaceAll("'","''").replaceAll('\r','\\r').replaceAll('\n','\\n')}'`;
function parameter(value){
 if(value===null)return 'NULL';
 if(typeof value==='string')return quoteText(value);
 if(typeof value==='number'&&Number.isFinite(value))return String(value);
 throw Error('NATIVE_SINGLE_PARAMETER_TYPE_UNSUPPORTED');
}
export function prepareSql(sql,values=[]){
 if(typeof sql!=='string'||!Array.isArray(values))throw Error('NATIVE_SINGLE_INPUT_SHAPE');
 let out='',i=0,previousLiteral=false;const used=new Set();
 const emitLiteral=token=>{if(previousLiteral)throw Error('NATIVE_SINGLE_ADJACENT_STRINGS_UNSUPPORTED');out+=token;previousLiteral=true;};
 while(i<sql.length){
  if(whitespace.test(sql[i])){while(i<sql.length&&whitespace.test(sql[i]))i++;out+=' ';continue;}
  if(sql.startsWith('--',i)){const end=sql.slice(i+2).search(/[\r\n]/);i=end<0?sql.length:i+2+end+1;out+=' ';continue;}
  if(sql.startsWith('/*',i)){
   let depth=1;i+=2;
   while(i<sql.length&&depth){if(sql.startsWith('/*',i)){depth++;i+=2;}else if(sql.startsWith('*/',i)){depth--;i+=2;}else i++;}
   if(depth)throw Error('NATIVE_SINGLE_UNTERMINATED_COMMENT');out+=' ';continue;
  }
  const boundary=i===0||!identifier.test(sql[i-1]);
  if(boundary&&/^[uU]&['"]/.test(sql.slice(i)))throw Error('NATIVE_SINGLE_UNICODE_QUOTES_UNSUPPORTED');
  if(boundary&&/^[bBxXnN]'/.test(sql.slice(i)))throw Error('NATIVE_SINGLE_PREFIXED_STRING_UNSUPPORTED');
  const escaped=boundary&&/[eE]/.test(sql[i])&&sql[i+1]==="'";
  if(escaped||sql[i]==="'"){
   i+=escaped?2:1;let content='',closed=false;
   while(i<sql.length){
    const ch=sql[i++];
    if(ch==="'"){if(sql[i]==="'"){content+=escaped?"''":"'";i++;continue;}closed=true;break;}
    if(escaped&&ch==='\\'){
     if(i>=sql.length)throw Error('NATIVE_SINGLE_UNTERMINATED_STRING');
     const next=sql[i++];content+=next==='\n'?'\\n':next==='\r'?'\\r':'\\'+next;continue;
    }
    content+=escaped&&ch==='\n'?'\\n':escaped&&ch==='\r'?'\\r':ch;
   }
   if(!closed)throw Error('NATIVE_SINGLE_UNTERMINATED_STRING');
   emitLiteral(escaped?`E'${content}'`:quoteText(content));continue;
  }
  if(sql[i]==='"'){
   const start=i++;let closed=false;
   while(i<sql.length){if(sql[i]==='\n'||sql[i]==='\r')throw Error('NATIVE_SINGLE_MULTILINE_IDENTIFIER_UNSUPPORTED');if(sql[i++]==='"'){if(sql[i]==='"'){i++;continue;}closed=true;break;}}
   if(!closed)throw Error('NATIVE_SINGLE_UNTERMINATED_IDENTIFIER');out+=sql.slice(start,i);previousLiteral=false;continue;
  }
  if(boundary&&sql[i]==='$'){
   const tag=sql.slice(i).match(/^\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$/)?.[0];
   if(tag){const end=sql.indexOf(tag,i+tag.length);if(end<0)throw Error('NATIVE_SINGLE_UNTERMINATED_DOLLAR_STRING');emitLiteral(quoteText(sql.slice(i+tag.length,end)));i=end+tag.length;continue;}
   const position=sql.slice(i).match(/^\$([0-9]+)/);
   if(position){
    const digits=position[1],index=Number(digits),end=i+position[0].length;
    if(!/^[1-9][0-9]*$/.test(digits)||!Number.isSafeInteger(index)||identifier.test(sql[end]??'')||index>values.length)throw Error('NATIVE_SINGLE_PARAMETER_COUNT');
    out+=parameter(values[index-1]);used.add(index);i=end;previousLiteral=false;continue;
   }
   throw Error('NATIVE_SINGLE_DOLLAR_FORM_UNSUPPORTED');
  }
  out+=sql[i++];previousLiteral=false;
 }
 if(used.size!==values.length)throw Error('NATIVE_SINGLE_UNUSED_PARAMETER');
 // Whitespace is normalized only in code; literal bytes are encoded above.
 // SQL tokens inside comments/strings never bind parameters.
 return out.replace(/^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g,'').replace(/;+$/,'');
}
